  const paths = ["/", AGENT_ENTRY_PATH, BRIDGE_PATH, LAB_RECORD_PATH, "/schedule", "/schedule/example"];
  const urls = paths.map((path) => `  <url><loc>${escapeXml(`${PUBLIC_ORIGIN}${path}`)}</loc></url>`).join("\n");
