function validateBriarwoodReferralExpiry(response) {
  if (response?.referral_state !== "offered") {
    return { valid: true, errors: [] };
  }
  const responseValidUntilMs = Date.parse(response.valid_until_utc);
  const referralValidUntilMs = Date.parse(
    response.referral_offer?.valid_until_utc
  );
  const valid = Number.isFinite(responseValidUntilMs) && Number.isFinite(referralValidUntilMs) && referralValidUntilMs >= responseValidUntilMs;
  return {
    valid,
    errors: valid ? [] : [BRIARWOOD_REFERRAL_EXPIRY_INVARIANT]
  };
}
