function createBriarwoodInquirySchema() {
  const referralStates = [
    "not_requested",
    "not_available",
    "offered",
    "accepted",
    "declined",
    "expired"
  ];
  return {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    $id: `${PUBLIC_ORIGIN}${BRIARWOOD_INQUIRY_SCHEMA_PATH}`,
    title: "Briarwood Participant-Local Inquiry Exchange",
    description: "Read-only contract for a direct node-to-node inquiry, scoped response, expiry, and optional authorized referral. 767-2676.com publishes this contract and stores or answers no inquiry instances.",
    type: "object",
    additionalProperties: false,
    required: [
      "schema_version",
      "exchange_id",
      "record_state",
      "operational",
      "signature_material_state",
      "request",
      "response",
      "verification_sequence",
      "storage_contract"
    ],
    properties: {
      schema_version: { type: "string", const: "1.0.0" },
      exchange_id: { $ref: "#/$defs/machine_identifier" },
      record_state: {
        type: "string",
        enum: ["example", "active", "terminal"]
      },
      operational: { type: "boolean" },
      signature_material_state: {
        type: "string",
        enum: ["live", "placeholder_non_verifiable"]
      },
      request: { $ref: "#/$defs/inquiry_request" },
      response: { $ref: "#/$defs/inquiry_response" },
      verification_sequence: {
        type: "array",
        minItems: 7,
        uniqueItems: true,
        items: {
          type: "string",
          enum: [
            "verify_request_message_attestation",
            "verify_request_popcorn_anchor",
            "validate_execution_window_utc",
            "apply_responder_local_policy",
            "verify_response_message_attestation",
            "verify_response_popcorn_anchor",
            "enforce_response_valid_until_utc",
            "select_authorized_referral_or_terminate"
          ]
        }
      },
      storage_contract: { $ref: "#/$defs/storage_contract" }
    },
    $defs: {
      machine_identifier: {
        type: "string",
        minLength: 1,
        maxLength: 160,
        pattern: "^[A-Za-z0-9](?:[A-Za-z0-9._:@/-]*[A-Za-z0-9])?$"
      },
      node_id: {
        type: "string",
        minLength: 1,
        maxLength: MAX_NODE_ID_LENGTH,
        pattern: "^[A-Za-z0-9](?:[A-Za-z0-9._:@/-]*[A-Za-z0-9])?$"
      },
      execution_window_utc: {
        type: "object",
        additionalProperties: false,
        required: ["opens_at_utc", "closes_at_utc"],
        properties: {
          opens_at_utc: { type: "string", format: "date-time" },
          closes_at_utc: { type: "string", format: "date-time" }
        }
      },
      popcorn_anchor: {
        type: "object",
        description: "Bearer temporal evidence from 767-2676.com. POPCORN signs time only and does not sign or authorize the inquiry, response, resource, or referral.",
        additionalProperties: false,
        required: [
          "anchor_id",
          "node_id",
          "protocol_id",
          "time_utc",
          "valid_until_utc",
          "evidence_scope",
          "verification_key_set_url",
          "compact_jws"
        ],
        properties: {
          anchor_id: { $ref: "#/$defs/machine_identifier" },
          node_id: { type: "string", const: NODE_ID },
          protocol_id: { type: "string", const: PROTOCOL_ID },
          time_utc: { type: "string", format: "date-time" },
          valid_until_utc: { type: "string", format: "date-time" },
          evidence_scope: {
            type: "string",
            const: "bearer_temporal_evidence"
          },
          verification_key_set_url: {
            type: "string",
            const: `${PUBLIC_ORIGIN}${POPCORN_KEYS_PATH}`
          },
          compact_jws: { type: "string", minLength: 1 }
        }
      },
      participant_attestation: {
        type: "object",
        description: "Participant signature over the RFC 8785 canonical JSON representation of the containing message with message_attestation omitted. This binds the participant assertion to the included POPCORN anchor_id without changing POPCORN's time-only evidence scope.",
        additionalProperties: false,
        required: [
          "format",
          "algorithm",
          "key_id",
          "verification_key_set_url",
          "payload_serialization",
          "payload_scope",
          "compact_jws"
        ],
        properties: {
          format: { type: "string", const: "JWS" },
          algorithm: { type: "string", enum: ["ES256", "EdDSA"] },
          key_id: { $ref: "#/$defs/machine_identifier" },
          verification_key_set_url: {
            type: "string",
            format: "uri",
            pattern: "^https://"
          },
          payload_serialization: { type: "string", const: "RFC8785-JCS" },
          payload_scope: {
            type: "string",
            const: "containing_message_without_message_attestation"
          },
          compact_jws: { type: "string", minLength: 1 }
        }
      },
      inquiry_request: {
        type: "object",
        additionalProperties: false,
        required: [...BRIARWOOD_INQUIRY_REQUIRED_FIELDS],
        properties: {
          protocol_id: {
            type: "string",
            const: BRIARWOOD_INQUIRY_PROTOCOL_ID
          },
          message_type: { type: "string", const: "inquiry_request" },
          inquiry_id: { $ref: "#/$defs/machine_identifier" },
          node_id: { $ref: "#/$defs/node_id" },
          resource_id: { $ref: "#/$defs/machine_identifier" },
          task_payload: {
            type: "object",
            description: "Narrow machine-native inquiry only. Private schedules, pricing, identity data, and unrelated task state remain participant-local."
          },
          execution_window_utc: { $ref: "#/$defs/execution_window_utc" },
          popcorn_anchor: { $ref: "#/$defs/popcorn_anchor" },
          message_attestation: { $ref: "#/$defs/participant_attestation" }
        }
      },
      referral_offer: {
        type: "object",
        additionalProperties: false,
        required: [
          "node_id",
          "inquiry_endpoint",
          "authorization_reference",
          "disclosure_scope",
          "valid_until_utc"
        ],
        properties: {
          node_id: { $ref: "#/$defs/node_id" },
          inquiry_endpoint: {
            type: "string",
            format: "uri",
            pattern: "^https://"
          },
          authorization_reference: { $ref: "#/$defs/machine_identifier" },
          disclosure_scope: { type: "string", const: "single_inquiry" },
          valid_until_utc: { type: "string", format: "date-time" }
        }
      },
      inquiry_response: {
        type: "object",
        additionalProperties: false,
        required: [...BRIARWOOD_RESPONSE_REQUIRED_FIELDS],
        properties: {
          protocol_id: {
            type: "string",
            const: BRIARWOOD_INQUIRY_PROTOCOL_ID
          },
          message_type: { type: "string", const: "inquiry_response" },
          inquiry_id: { $ref: "#/$defs/machine_identifier" },
          node_id: { $ref: "#/$defs/node_id" },
          resource_id: { $ref: "#/$defs/machine_identifier" },
          availability_state: {
            type: "string",
            enum: [...BRIARWOOD_AVAILABILITY_STATES]
          },
          valid_until_utc: { type: "string", format: "date-time" },
          next_action: {
            type: "string",
            enum: [...BRIARWOOD_INQUIRY_NEXT_ACTIONS]
          },
          referral_state: { type: "string", enum: referralStates },
          referral_offer: { $ref: "#/$defs/referral_offer" },
          popcorn_anchor: { $ref: "#/$defs/popcorn_anchor" },
          message_attestation: { $ref: "#/$defs/participant_attestation" }
        },
        allOf: [
          {
            if: {
              required: ["referral_state"],
              properties: { referral_state: { const: "offered" } }
            },
            then: { required: ["referral_offer"] }
          }
        ]
      },
      storage_contract: {
        type: "object",
        additionalProperties: false,
        required: [
          "storage_scope",
          "popcorn_stores_exchange",
          "global_inquiry_registry",
          "global_availability_registry",
          "retained_records",
          "cleared_ephemeral_state"
        ],
        properties: {
          storage_scope: { type: "string", const: "participant_local" },
          popcorn_stores_exchange: { type: "boolean", const: false },
          global_inquiry_registry: { type: "boolean", const: false },
          global_availability_registry: { type: "boolean", const: false },
          retained_records: {
            type: "array",
            uniqueItems: true,
            items: {
              type: "string",
              enum: [
                "signed_inquiry_request",
                "signed_inquiry_response",
                "verified_popcorn_receipts",
                "participant_local_decision_receipt"
              ]
            }
          },
          cleared_ephemeral_state: {
            type: "array",
            uniqueItems: true,
            items: {
              type: "string",
              enum: [
                "retry_counter",
                "transient_route_state",
                "payment_proof",
                "unselected_referral_candidates"
              ]
            }
          }
        }
      }
    },
    "x-briarwood-contract": {
      protocol_id: BRIARWOOD_INQUIRY_PROTOCOL_ID,
      publication_scope: "read_only_contract_and_example",
      transport_scope: "participant_to_participant",
      participant_storage_required: true,
      node_operates_global_inquiry_endpoint: false,
      node_stores_inquiry_instances: false,
      global_availability_registry: false,
      global_referral_registry: false,
      initial_peer_state: { peers: [] },
      assertion_boundaries: {
        popcorn_asserts: ["time_utc", "valid_until_utc", "temporal_origin"],
        participant_asserts: [
          "inquiry_contents",
          "availability_state",
          "response_valid_until_utc",
          "authorized_referral_offer"
        ],
        popcorn_task_bound: false,
        participant_message_binds_popcorn_anchor_id: true
      },
      semantic_validation: [
        "request_and_response_inquiry_id_must_match",
        "request_and_response_resource_id_must_match",
        "execution_window_close_must_follow_open",
        "both_popcorn_compact_jws_values_must_verify_against_the_pinned_popcorn_jwks",
        "both_participant_message_attestations_must_verify_against_the_declared_participant_jwks",
        "participant_jws_payload_must_equal_rfc8785_canonical_message_without_message_attestation",
        "popcorn_anchor_id_must_be_covered_by_the_participant_message_attestation",
        "popcorn_evidence_proves_time_only_and_must_not_be_treated_as_availability_or_authorization",
        "response_valid_until_utc_must_be_enforced_by_the_requesting_node",
        "referral_offer_requires_explicit_participant_local_authorization",
        BRIARWOOD_REFERRAL_EXPIRY_INVARIANT,
        "retry_must_stop_at_execution_window_close"
      ]
    }
  };
}
