function createExecutionScheduleSchema() {
  const terminalStates = ["completed", "expired", "released", "handed_off"];
  return {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    $id: `${PUBLIC_ORIGIN}${EXECUTION_SCHEDULE_SCHEMA_PATH}`,
    title: "POPCORN Portable Execution Schedule",
    description: "Read-only contract for an agent-carried, participant-local sequence of time-bounded execution events. 767-2676.com publishes this schema and stores no schedule instances.",
    type: "object",
    additionalProperties: false,
    required: [
      "schema_version",
      "schedule_id",
      "schedule_revision",
      "node_id",
      "issued_at_utc",
      "valid_until_utc",
      "schedule_state",
      "current_event_id",
      "outcome_payload",
      "coordination_policy",
      "events"
    ],
    properties: {
      schema_version: { type: "string", const: "1.0.0" },
      schedule_id: { $ref: "#/$defs/machine_identifier" },
      schedule_revision: { type: "integer", minimum: 1 },
      node_id: {
        type: "string",
        minLength: 1,
        maxLength: MAX_NODE_ID_LENGTH,
        pattern: "^[A-Za-z0-9](?:[A-Za-z0-9._:@/-]*[A-Za-z0-9])?$"
      },
      issued_at_utc: { type: "string", format: "date-time" },
      valid_until_utc: { type: "string", format: "date-time" },
      schedule_state: {
        type: "string",
        enum: ["active", "completed", "expired", "cancelled"]
      },
      current_event_id: {
        oneOf: [{ $ref: "#/$defs/machine_identifier" }, { type: "null" }]
      },
      outcome_payload: {
        type: "object",
        description: "Participant-local definition of the required result that schedule recovery must preserve."
      },
      coordination_policy: { $ref: "#/$defs/coordination_policy" },
      events: {
        type: "array",
        minItems: 1,
        maxItems: 1e3,
        items: { $ref: "#/$defs/execution_event" }
      }
    },
    $defs: {
      machine_identifier: {
        type: "string",
        minLength: 1,
        maxLength: 160,
        pattern: "^[A-Za-z0-9](?:[A-Za-z0-9._:@/-]*[A-Za-z0-9])?$"
      },
      execution_window_utc: {
        type: "object",
        additionalProperties: false,
        required: ["opens_at_utc", "closes_at_utc"],
        properties: {
          opens_at_utc: { type: "string", format: "date-time" },
          closes_at_utc: { type: "string", format: "date-time" }
        }
      },
      planned_execution_utc: {
        type: "object",
        additionalProperties: false,
        required: ["starts_at_utc", "ends_at_utc"],
        properties: {
          starts_at_utc: { type: "string", format: "date-time" },
          ends_at_utc: { type: "string", format: "date-time" }
        }
      },
      attempt_policy: {
        type: "object",
        additionalProperties: false,
        required: ["max_attempts", "backoff", "stop_at_window_close"],
        properties: {
          max_attempts: { type: "integer", minimum: 1, maximum: 100 },
          backoff: {
            type: "string",
            const: "bounded_exponential_with_jitter"
          },
          stop_at_window_close: { type: "boolean", const: true }
        }
      },
      coordination_policy: {
        type: "object",
        additionalProperties: false,
        required: [
          "time_source",
          "drift_measurement",
          "recovery_mode",
          "outcome_priority",
          "allow_independent_event_resequence",
          "stop_at_schedule_close",
          "unbounded_retry"
        ],
        properties: {
          time_source: { type: "string", const: "popcorn_temporal_anchor" },
          drift_measurement: {
            type: "string",
            const: "observed_time_minus_planned_time_ms"
          },
          recovery_mode: {
            type: "string",
            const: "bounded_resequence_remaining_events"
          },
          outcome_priority: {
            type: "string",
            const: "preserve_required_outcome"
          },
          allow_independent_event_resequence: { type: "boolean" },
          stop_at_schedule_close: { type: "boolean", const: true },
          unbounded_retry: { type: "boolean", const: false }
        }
      },
      timing_policy: {
        type: "object",
        additionalProperties: false,
        required: [
          "expected_duration_ms",
          "buffer_after_ms",
          "drift_tolerance_ms"
        ],
        properties: {
          expected_duration_ms: { type: "integer", minimum: 0 },
          buffer_after_ms: { type: "integer", minimum: 0 },
          drift_tolerance_ms: { type: "integer", minimum: 0 }
        }
      },
      execution_context: {
        type: "object",
        additionalProperties: false,
        required: [
          "assigned_node_ids",
          "location_mode",
          "origin_location_ref",
          "destination_location_ref"
        ],
        properties: {
          assigned_node_ids: {
            type: "array",
            minItems: 1,
            uniqueItems: true,
            items: {
              type: "string",
              minLength: 1,
              maxLength: MAX_NODE_ID_LENGTH
            }
          },
          location_mode: {
            type: "string",
            enum: ["physical", "network", "hybrid", "not_applicable"]
          },
          origin_location_ref: {
            oneOf: [
              { type: "string", minLength: 1, maxLength: 2048 },
              { type: "null" }
            ]
          },
          destination_location_ref: {
            oneOf: [
              { type: "string", minLength: 1, maxLength: 2048 },
              { type: "null" }
            ]
          }
        }
      },
      drift_state: {
        type: "object",
        additionalProperties: false,
        required: [
          "observed_drift_ms",
          "reason_code",
          "recovery_action",
          "recalculated_at_utc"
        ],
        properties: {
          observed_drift_ms: { type: "integer" },
          reason_code: {
            type: "string",
            enum: [
              "execution_delay",
              "dependency_delay",
              "resource_unavailable",
              "network_delay",
              "policy_interruption",
              "unknown"
            ]
          },
          recovery_action: {
            type: "string",
            enum: [
              "continue",
              "compress_buffer",
              "resequence_independent_events",
              "handoff_event",
              "release_event",
              "terminate_event"
            ]
          },
          recalculated_at_utc: { type: "string", format: "date-time" }
        }
      },
      popcorn_anchor: {
        type: "object",
        additionalProperties: false,
        required: ["anchor_id", "time_utc", "valid_until_utc", "compact_jws"],
        properties: {
          anchor_id: { $ref: "#/$defs/machine_identifier" },
          time_utc: { type: "string", format: "date-time" },
          valid_until_utc: { type: "string", format: "date-time" },
          compact_jws: { type: "string", minLength: 1 }
        }
      },
      terminal_receipt: {
        type: "object",
        additionalProperties: false,
        required: [
          "receipt_id",
          "terminal_state",
          "recorded_at_utc",
          "task_payload_digest"
        ],
        properties: {
          receipt_id: { $ref: "#/$defs/machine_identifier" },
          terminal_state: { type: "string", enum: terminalStates },
          recorded_at_utc: { type: "string", format: "date-time" },
          task_payload_digest: {
            type: "string",
            pattern: "^sha256:[A-Za-z0-9_-]{43}$"
          }
        }
      },
      execution_event: {
        type: "object",
        additionalProperties: false,
        required: [
          "event_id",
          "sequence_index",
          "resource_id",
          "task_payload",
          "execution_window_utc",
          "planned_execution_utc",
          "execution_context",
          "dependency_event_ids",
          "timing_policy",
          "state",
          "next_action",
          "attempt_policy"
        ],
        properties: {
          event_id: { $ref: "#/$defs/machine_identifier" },
          sequence_index: { type: "integer", minimum: 0 },
          resource_id: { $ref: "#/$defs/machine_identifier" },
          task_payload: { type: "object" },
          task_payload_digest: {
            type: "string",
            pattern: "^sha256:[A-Za-z0-9_-]{43}$"
          },
          execution_window_utc: { $ref: "#/$defs/execution_window_utc" },
          planned_execution_utc: { $ref: "#/$defs/planned_execution_utc" },
          execution_context: { $ref: "#/$defs/execution_context" },
          dependency_event_ids: {
            type: "array",
            uniqueItems: true,
            items: { $ref: "#/$defs/machine_identifier" }
          },
          timing_policy: { $ref: "#/$defs/timing_policy" },
          drift_state: { $ref: "#/$defs/drift_state" },
          state: {
            type: "string",
            enum: [
              "scheduled",
              "eligible",
              "executing",
              "delayed",
              "recovering",
              ...terminalStates
            ]
          },
          next_action: {
            type: "string",
            enum: [
              "await_window",
              "ground_time",
              "execute_task",
              "measure_drift",
              "resequence_schedule",
              "resume_task",
              "advance_schedule",
              "terminate_schedule",
              "release_resource",
              "submit_handoff"
            ]
          },
          attempt_policy: { $ref: "#/$defs/attempt_policy" },
          popcorn_anchor: { $ref: "#/$defs/popcorn_anchor" },
          terminal_receipt: { $ref: "#/$defs/terminal_receipt" }
        },
        allOf: [
          {
            if: {
              required: ["state"],
              properties: { state: { enum: terminalStates } }
            },
            then: { required: ["terminal_receipt"] }
          }
        ]
      }
    },
    "x-popcorn-contract": {
      time_anchor_endpoint: MACHINE_TIME_PATH,
      time_anchor_legacy_endpoint: "/time?format=json",
      storage_scope: "participant_local",
      transport_scope: "agent_carried",
      node_stores_schedule_instances: false,
      state_machine: {
        initial_state: "scheduled",
        active_states: ["eligible", "executing", "delayed", "recovering"],
        terminal_states: terminalStates
      },
      judgment_contract: {
        inputs: [
          "execution_window_utc",
          "planned_execution_utc",
          "execution_context",
          "dependency_event_ids",
          "timing_policy",
          "drift_state",
          "outcome_payload"
        ],
        within_tolerance_action: "continue",
        outside_tolerance_action: "increment_schedule_revision_and_resequence_remaining_events",
        outcome_priority: "preserve_required_outcome",
        schedule_close_is_terminal: true
      },
      semantic_validation: [
        "schedule_valid_until_utc_must_follow_issued_at_utc",
        "execution_window_close_must_follow_open",
        "planned_execution_end_must_follow_start",
        "planned_execution_must_fit_within_execution_window",
        "expected_duration_ms_must_match_planned_execution_duration",
        "event_windows_must_fit_within_schedule_validity",
        "event_ids_must_be_unique",
        "sequence_indexes_must_be_unique_and_contiguous",
        "dependency_event_ids_must_resolve_and_be_acyclic",
        "current_event_id_must_resolve_or_be_null",
        "assigned_node_ids_must_be_participant_authorized",
        "location_refs_must_be_participant_authorized",
        "non_null_location_refs_required_unless_location_mode_not_applicable",
        "popcorn_anchor_must_be_valid_at_each_time_judgment",
        "observed_drift_ms_must_be_derived_from_the_planned_timeline",
        "resequence_must_increment_schedule_revision",
        "resequence_must_not_reopen_terminal_events",
        "terminal_receipt_state_must_match_event_state",
        "recovery_must_not_extend_execution_beyond_schedule_close"
      ],
      reset_contract: {
        trigger: "terminal_receipt_recorded",
        retain: ["terminal_receipt"],
        clear_before_next_event: [
          "resource_lock",
          "payment_proof",
          "retry_counter",
          "transient_task_state"
        ]
      }
    }
  };
}
